using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class T01GuideScope {
 public static object Run(){var root=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var group=root.Find("Facility_Floor_Guidance_R1");var p=new Vector3(-17.23132775f,-82,-1.074689f);var q=Quaternion.LookRotation(new Vector3(-.242535625f,0,.9701425f));float maxXZ=0,maxY=0;int outside=0;foreach(string side in new[]{"L","R"}){var original=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Afrer_Seconds/05.Model/Environment/B5/CF_R1_Continuous_"+side+".asset").vertices;var target=group.GetComponentsInChildren<MeshFilter>().Single(m=>m.sharedMesh.name.EndsWith("_"+side));var vs=target.sharedMesh.vertices;for(int i=0;i<vs.Length;i++){var world=target.transform.TransformPoint(vs[i]);float z=(Quaternion.Inverse(q)*(world-p)).z;if(z>=.01f&&z<=13.45174f)continue;outside++;float distance=float.MaxValue;for(int k=i%2;k<original.Length-2;k+=2){var a=group.TransformPoint(original[k]);var b=group.TransformPoint(original[k+2]);var pt=new Vector2(world.x,world.z);var av=new Vector2(a.x,a.z);var bv=new Vector2(b.x,b.z);var d=bv-av;float t=Mathf.Clamp01(Vector2.Dot(pt-av,d)/d.sqrMagnitude);distance=Mathf.Min(distance,Vector2.Distance(pt,av+d*t));}maxXZ=Mathf.Max(maxXZ,distance);if(z<-.8f||z>14.26174f)maxY=Mathf.Max(maxY,Mathf.Abs(world.y-(-81.982f)));}}
 var result=new{outsideVertexSamples=outside,maxOutsideXZChange=maxXZ,maxOutsidePortalHeightChange=maxY,heightException="Only 0.8m around T01 thresholds: paint follows the physical sill",passed=maxXZ<.0001f&&maxY<.0001f};File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-07_T01_Corridor/guide_scope.json")),JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
